      "target_block_ref": "decide"
    },
    {
      "source_block_ref": "decide",
      "target_block_ref": "send_alert",
      "condition_text": "urgent"
    },
    {
      "source_block_ref": "decide",
      "target_block_ref": "skip_alert",
