        }
      },
      "required": [
        "source_block_ref",
        "target_block_ref"
      ],
      "title": "CandidateEdge",
      "type": "object"
    },
    "CandidateInstruction": {
      "additionalProperties": false,
      "description": "An instruction proposed by the LLM before canonical compilation.",
      "properties": {
        "instruction_ref": {
          "title": "Instruction Ref",
          "type": "string"
        },
